import{_ as s,o as i,c as a,a2 as n}from"./chunks/framework.k0yuBbP4.js";const c=JSON.parse('{"title":"Troubleshooting","description":"Fixes for the problems gulp 5 builds run into with gulp-plugins-hub - corrupted binary files, CommonJS and TypeScript gulpfiles, native binaries in CI and Windows paths.","frontmatter":{"description":"Fixes for the problems gulp 5 builds run into with gulp-plugins-hub - corrupted binary files, CommonJS and TypeScript gulpfiles, native binaries in CI and Windows paths."},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1792488962000}'),o={name:"guide/troubleshooting.md"};function t(l,e,r,p,d,h){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="images-fonts-or-archives-come-out-corrupted" tabindex="-1">Images, fonts or archives come out corrupted <a class="header-anchor" href="#images-fonts-or-archives-come-out-corrupted" aria-label="Permalink to &quot;Images, fonts or archives come out corrupted&quot;">​</a></h2><p>Gulp 5 reads every file as UTF-8 text unless told otherwise, and every byte that is not valid UTF-8 becomes <code>U+FFFD</code>. <a href="/gulp-plugins-hub/plugins/image-squeezer">image-squeezer</a> and <a href="/gulp-plugins-hub/plugins/font-switcher">font-switcher</a> notice and fail with the fix:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error in plugin &quot;@zilero/gulp-image-squeezer&quot;</span></span>
<span class="line"><span>Message:</span></span>
<span class="line"><span>    images/hero.jpg was read as UTF-8 text and is corrupted. Read binary files with \`src(globs, { encoding: false })\`</span></span></code></pre></div><p>Read binary files with <code>encoding: false</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;src/images/**&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { encoding: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>Plugins that only copy, rename or pack files (<a href="/gulp-plugins-hub/plugins/archive-creator">archive-creator</a>, <a href="/gulp-plugins-hub/plugins/asset-revision">asset-revision</a>, <a href="/gulp-plugins-hub/plugins/folder-clone">folder-clone</a>, <a href="/gulp-plugins-hub/plugins/refilename">refilename</a>) cannot tell a corrupted file from a good one: give them <code>encoding: false</code> too whenever the stream has binary files. Text plugins work with either; <a href="/gulp-plugins-hub/plugins/text-replace">text-replace</a> leaves files with a NUL byte alone.</p><h2 id="require-of-the-plugins-in-a-commonjs-gulpfile" tabindex="-1"><code>require()</code> of the plugins in a CommonJS gulpfile <a class="header-anchor" href="#require-of-the-plugins-in-a-commonjs-gulpfile" aria-label="Permalink to &quot;\`require()\` of the plugins in a CommonJS gulpfile&quot;">​</a></h2><p>The packages are ES modules. Node.js 22.12 and newer load them with <code>require</code>, through the named export:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// gulpfile.js (CommonJS)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">scssCompiler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@zilero/gulp-scss-compiler&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><ul><li><code>scssCompiler is not a function</code>: <code>require</code> returns the module namespace, so the default export is <code>require(…).default</code>. Use the named export.</li><li><code>ERR_REQUIRE_ESM</code>: the Node.js version is older than 22.12. The packages need 22.13 or newer.</li><li>On some 22.x releases Node.js prints an <code>ExperimentalWarning</code> for <code>require()</code> of an ES module. It is harmless; moving the gulpfile to ES modules (<code>gulpfile.mjs</code>, or <code>&quot;type&quot;: &quot;module&quot;</code>) removes it.</li></ul><h2 id="a-typescript-gulpfile-does-not-load" tabindex="-1">A TypeScript gulpfile does not load <a class="header-anchor" href="#a-typescript-gulpfile-does-not-load" aria-label="Permalink to &quot;A TypeScript gulpfile does not load&quot;">​</a></h2><p>gulp-cli loads <code>gulpfile.ts</code> through a register module, tried in a fixed order: ts-node, sucrase, @babel/register, esbuild-register, @swc/register. Node&#39;s built-in type stripping is not registered for <code>require</code>, which gulp-cli uses, so it does not help here.</p><ul><li><code>Failed to load external module …</code> for each of them: none is installed. Install <code>esbuild-register</code> and <code>esbuild</code>.</li><li>The gulpfile fails to load with <code>&quot;type&quot;: &quot;module&quot;</code> although esbuild-register is installed, and the log says <code>Loaded external module: sucrase/register/ts</code>: sucrase is picked before esbuild-register, and it does not handle ES modules. <code>npm ls sucrase</code> shows what brings it in; remove it.</li><li><code>Top-level await is currently not supported with the &quot;cjs&quot; output format</code>: the register modules compile the gulpfile to CommonJS. Move the <code>await</code> into a task.</li></ul><p><a href="/gulp-plugins-hub/guide/gulp-5#es-modules-and-typescript-gulpfiles">Gulp 5 essentials</a> has the setup; the <a href="/gulp-plugins-hub/guide/example-project">example project</a> uses it.</p><h2 id="native-binaries-missing-in-ci-or-docker" tabindex="-1">Native binaries missing in CI or Docker <a class="header-anchor" href="#native-binaries-missing-in-ci-or-docker" aria-label="Permalink to &quot;Native binaries missing in CI or Docker&quot;">​</a></h2><p><a href="/gulp-plugins-hub/plugins/image-squeezer">image-squeezer</a> (sharp), <a href="/gulp-plugins-hub/plugins/scss-compiler">scss-compiler</a> (sass-embedded) and <a href="/gulp-plugins-hub/plugins/css-squeezer">css-squeezer</a> (Lightning CSS) ship a prebuilt binary per platform as an optional dependency, such as <code>@img/sharp-linux-x64</code>, <code>sass-embedded-linux-x64</code> or <code>lightningcss-linux-x64-gnu</code>. The package manager installs only the one for the machine it runs on. Errors like <code>Could not load the &quot;sharp&quot; module using the linux-x64 runtime</code> or <code>Cannot find module &#39;lightningcss-linux-x64-gnu&#39;</code> mean that binary is missing:</p><ul><li>Install on the machine (or in the image) that runs the build. A <code>node_modules</code> copied from macOS or Windows into a Linux container has the wrong binaries.</li><li>Do not skip optional dependencies: no <code>--omit=optional</code>, <code>--no-optional</code> or <code>optional=false</code> in <code>.npmrc</code>.</li><li>Alpine and other musl images need the <code>musl</code> builds; they install when <code>npm install</code> runs inside that image.</li><li>With npm, a lockfile written on one platform can miss the optional packages of another. Run <code>npm install</code> once more on the CI platform, or install them explicitly: <code>npm install --os=linux --cpu=x64 sharp</code>. Bun and pnpm keep every platform in the lockfile.</li></ul><p>font-switcher uses WebAssembly, so it has no native binary.</p><h2 id="paths-on-windows" tabindex="-1">Paths on Windows <a class="header-anchor" href="#paths-on-windows" aria-label="Permalink to &quot;Paths on Windows&quot;">​</a></h2><p><code>file.relative</code> and <code>file.path</code> use the platform&#39;s separator, so on Windows they contain <code>\\</code>. Globs and regular expressions in plugin options are matched against the path with <code>/</code> on every platform: write <code>&#39;images/**/*.png&#39;</code> or <code>/^images\\//</code> and they work everywhere.</p><p>In your own hooks and conditions, compare paths the same way:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;node:path&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> relative</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> file.relative.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">split</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path.sep).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">join</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Names the plugins write into files (archive entries, the asset-revision manifest, source map sources, error messages) always use <code>/</code>.</p><h2 id="a-task-hangs-at-starting" tabindex="-1">A task hangs at &quot;Starting…&quot; <a class="header-anchor" href="#a-task-hangs-at-starting" aria-label="Permalink to &quot;A task hangs at &quot;Starting…&quot;&quot;">​</a></h2><p>A stream in the middle of a <code>.pipe()</code> chain failed, and gulp never heard the task end. Return <code>pipeline(…)</code> from <code>node:stream/promises</code> instead: the task then ends with the error (<a href="/gulp-plugins-hub/guide/gulp-5#return-pipeline-not-a-pipe-chain">why</a>).</p><h2 id="invalid-options-before-any-file-is-read" tabindex="-1"><code>Invalid options</code> before any file is read <a class="header-anchor" href="#invalid-options-before-any-file-is-read" aria-label="Permalink to &quot;\`Invalid options\` before any file is read&quot;">​</a></h2><p>Every plugin validates its options when it is created and lists every problem:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error in plugin &quot;@zilero/gulp-css-squeezer&quot;</span></span>
<span class="line"><span>Message:</span></span>
<span class="line"><span>    Invalid options:</span></span>
<span class="line"><span>    • Unrecognized key: &quot;minfy&quot;</span></span></code></pre></div><p>Unknown keys are errors, so a typo or an option name from another plugin shows up here instead of being ignored. The plugin&#39;s page lists its options, and <a href="/gulp-plugins-hub/guide/migrating-from-other-plugins">Migrating from other plugins</a> maps the common ones.</p>`,30)])])}const g=s(o,[["render",t]]);export{c as __pageData,g as default};
